/* ============================================================
   1. ECG — CHỈ HIỆN HAI BÊN TRÁI TIM
============================================================ */

drawECG = function (now) {

    ectx.clearRect(0, 0, W, H);

    if (!started) return;


    const centerY = H * 0.47;

    /*
        Khoảng cách từ ECG tới tim.
        Số càng lớn -> ECG càng xa tim.
    */

    const heartGap =
        W < 650
            ? W * 0.27
            : W * 0.205;


    /*
        ECG phản ứng trực tiếp với heartBeat.
    */

    const beatPower =
        15 + heartBeat * 55;


    ectx.lineWidth =
        1.15 + heartBeat * 1.15;


    ectx.lineCap =
        "round";


    ectx.lineJoin =
        "round";


    ectx.shadowColor =
        "rgba(255, 65, 150, .80)";


    ectx.shadowBlur =
        7 + heartBeat * 18;



    function drawSide(
        startX,
        endX,
        reverse
    ) {

        const width =
            endX - startX;


        const gradient =
            ectx.createLinearGradient(
                startX,
                0,
                endX,
                0
            );


        /*
            Sáng hơn khi tiến gần trái tim.
        */

        if (!reverse) {

            gradient.addColorStop(
                0,
                "rgba(255,80,155,0)"
            );

            gradient.addColorStop(
                0.30,
                "rgba(255,90,165,.11)"
            );

            gradient.addColorStop(
                0.72,
                "rgba(255,100,175,.23)"
            );

            gradient.addColorStop(
                1,
                `rgba(
                    255,
                    130,
                    190,
                    ${0.36 + heartBeat * 0.38}
                )`
            );

        } else {

            gradient.addColorStop(
                0,
                `rgba(
                    255,
                    130,
                    190,
                    ${0.36 + heartBeat * 0.38}
                )`
            );

            gradient.addColorStop(
                0.28,
                "rgba(255,100,175,.23)"
            );

            gradient.addColorStop(
                0.70,
                "rgba(255,90,165,.11)"
            );

            gradient.addColorStop(
                1,
                "rgba(255,80,155,0)"
            );

        }


        ectx.strokeStyle =
            gradient;


        ectx.beginPath();


        ectx.moveTo(
            startX,
            centerY
        );


        /*
            ECG:

            ______/\_______/\/\_______/\______

            P         QRS          T
        */

        const wave = [

            [0.00,  0.00],
            [0.12,  0.00],

            [0.22, -0.03],
            [0.29,  0.04],
            [0.35,  0.00],

            [0.49,  0.00],

            [0.58, -0.12],

            [0.65,  0.27],

            /*
                R spike
            */

            [0.72, -1.00],

            [0.78,  0.42],

            [0.84, -0.10],

            [0.88,  0.00],

            /*
                T wave
            */

            [0.93, -0.075],
            [0.97,  0.00],

            [1.00,  0.00]

        ];


        for (
            const [u, v]
            of wave
        ) {

            ectx.lineTo(

                startX +
                width * u,

                centerY +
                v * beatPower

            );

        }


        ectx.stroke();

    }



    /* ===========================
       ECG BÊN TRÁI
    =========================== */

    drawSide(

        W * 0.035,

        W * 0.5 -
        heartGap,

        false

    );



    /* ===========================
       ECG BÊN PHẢI
    =========================== */

    drawSide(

        W * 0.5 +
        heartGap,

        W * 0.965,

        true

    );


    ectx.shadowBlur = 0;

};



