/* ============================================================
   5. STORY ENGINE MỚI
============================================================ */

let v11StoryIndex =
    -1;


let v11StoryTimer =
    null;



function showV11Message(index) {

    /*
        Không chạy lại cùng một câu.
    */

    if (
        index ===
        v11StoryIndex
    ) {

        return;

    }


    if (
        index < 0 ||
        index >=
        STORY_LINES.length
    ) {

        return;

    }


    v11StoryIndex =
        index;


    /*
        Cho câu cũ biến mất.
    */

    messageBox.classList.remove(
        "message-visible"
    );


    messageBox.classList.add(
        "message-leaving"
    );


    messageBox.classList.remove(
        "final-message"
    );


    if (
        v11StoryTimer
    ) {

        clearTimeout(
            v11StoryTimer
        );

    }


    /*
        Sau khi câu cũ mờ đi,
        mới thay text.
    */

    v11StoryTimer =
        setTimeout(
            () => {


                messageText.textContent =
                    STORY_LINES[index];


                /*
                    Câu Nhật cuối.
                */

                if (
                    index ===
                    STORY_LINES.length - 1
                ) {

                    messageBox.classList.add(
                        "final-message"
                    );

                }


                messageBox.classList.remove(
                    "message-leaving"
                );


                /*
                    Force reflow để animation
                    luôn chạy.
                */

                void messageBox.offsetWidth;


                messageBox.classList.add(
                    "message-visible"
                );


            },

            220

        );

}



/* ============================================================
   6. GHI ĐÈ updateStory CŨ
============================================================ */

updateStory = function () {

    if (
        !started ||
        music.paused
    ) {

        return;

    }


    const currentTime =
        music.currentTime;


    /*
        Câu đầu bắt đầu sau khoảng 2.4 giây.
    */

    const START_TIME =
        2.4;


    /*
        Khoảng cách giữa các câu.

        3.35 giây/câu:
        đủ đọc,
        không kéo lê.
    */

    const LINE_TIME =
        3.35;


    if (
        currentTime <
        START_TIME
    ) {

        return;

    }


    let index =
        Math.floor(

            (
                currentTime -
                START_TIME
            )

            /

            LINE_TIME

        );


    index =
        Math.min(

            index,

            STORY_LINES.length - 1

        );


    showV11Message(
        index
    );

};



